{"command":"python3 - <<'EOF'
import sqlite3
for db in ("databases/source.db", "databases/target.db"):
    con = sqlite3.connect("file:%s?mode=ro" % db, uri=True)
    tabs = [r[0] for r in con.execute("SELECT name FROM sqlite_master WHERE type='table' ORDER BY name")]
    print(db, "tables:", tabs)
    for t in tabs:
        print("  %-16s %d" % (t, con.execute('SELECT COUNT(*) FROM "%s"' % t).fetchone()[0]))
    con.close()
EOF","workdir":"/testbed/migration-recon"}

